import type { AuthIR } from '@expo-foundation/core';
import { compileAuthFlows } from '../runtime/flow-compiler.js';

export interface GeneratedAuthFile {
  path: string;
  content: string;
  ownership: 'generated';
}

const GENERATED_HEADER = `/**
 * @generated by @expo-foundation/auth
 * DO NOT EDIT MANUALLY — deterministic output from auth.json via Canonical AuthIR.
 */`;

export function generateAuthFiles(authIR: AuthIR): GeneratedAuthFile[] {
  const flows = compileAuthFlows(authIR);
  const files: GeneratedAuthFile[] = [];

  // 1. src/foundation/config/auth.generated.ts
  files.push({
    path: 'src/foundation/config/auth.generated.ts',
    ownership: 'generated',
    content: `${GENERATED_HEADER}

export const AUTH_CONFIG = ${JSON.stringify(
      {
        id: authIR.id,
        enabled: authIR.enabled,
        primaryProvider: authIR.primaryProvider,
        authMethods: authIR.authMethods,
        sessionPolicy: authIR.sessionPolicy,
        accessContext: authIR.accessContext,
        screenRefs: authIR.screenRefs,
        events: authIR.events,
        workflows: flows,
      },
      null,
      2
    )} as const;

export type GeneratedAuthConfig = typeof AUTH_CONFIG;
`,
  });

  // 2. src/foundation/auth/SecureStorage.ts
  files.push({
    path: 'src/foundation/auth/SecureStorage.ts',
    ownership: 'generated',
    content: `${GENERATED_HEADER}
import * as SecureStore from 'expo-secure-store';

export interface SecureStorageAdapter {
  getItem(key: string): Promise<string | null>;
  setItem(key: string, value: string): Promise<void>;
  deleteItem(key: string): Promise<void>;
}

const MAX_SECURE_STORE_BYTES = 2048;

export class ExpoSecureStorage implements SecureStorageAdapter {
  async getItem(key: string): Promise<string | null> {
    return SecureStore.getItemAsync(key, {
      keychainAccessible: SecureStore.WHEN_UNLOCKED_THIS_DEVICE_ONLY,
    });
  }

  async setItem(key: string, value: string): Promise<void> {
    if (/password|clientSecret|privateKey/i.test(key) || /"password"|"clientSecret"/i.test(value)) {
      throw new Error('Security policy violation: never store passwords or secrets in SecureStore.');
    }
    if (value.length > MAX_SECURE_STORE_BYTES) {
      throw new Error('SecureStore payload exceeds 2048 bytes.');
    }
    await SecureStore.setItemAsync(key, value, {
      keychainAccessible: SecureStore.WHEN_UNLOCKED_THIS_DEVICE_ONLY,
    });
  }

  async deleteItem(key: string): Promise<void> {
    await SecureStore.deleteItemAsync(key);
  }
}
`,
  });

  // 3. src/foundation/auth/TokenManager.ts
  files.push({
    path: 'src/foundation/auth/TokenManager.ts',
    ownership: 'generated',
    content: `${GENERATED_HEADER}
import type { SecureStorageAdapter } from './SecureStorage';

export interface StoredSessionMetadata {
  sessionId: string;
  userId: string;
  roles: string[];
  permissions: string[];
  verified: boolean;
  expiresAt: number;
  tenantId?: string;
}

export class TokenManager {
  constructor(
    private readonly storage: SecureStorageAdapter,
    private readonly prefix = 'expo_foundation_auth'
  ) {}

  async saveTokens(params: {
    accessToken: string;
    refreshToken?: string;
    metadata: StoredSessionMetadata;
  }): Promise<void> {
    await this.storage.setItem(\`\${this.prefix}.access\`, params.accessToken);
    if (params.refreshToken) {
      await this.storage.setItem(\`\${this.prefix}.refresh\`, params.refreshToken);
    }
    await this.storage.setItem(\`\${this.prefix}.meta\`, JSON.stringify(params.metadata));
  }

  async getAccessToken(): Promise<string | null> {
    return this.storage.getItem(\`\${this.prefix}.access\`);
  }

  async getRefreshToken(): Promise<string | null> {
    return this.storage.getItem(\`\${this.prefix}.refresh\`);
  }

  async getMetadata(): Promise<StoredSessionMetadata | null> {
    const raw = await this.storage.getItem(\`\${this.prefix}.meta\`);
    if (!raw) return null;
    try {
      return JSON.parse(raw) as StoredSessionMetadata;
    } catch {
      return null;
    }
  }

  async clear(): Promise<void> {
    await Promise.all([
      this.storage.deleteItem(\`\${this.prefix}.access\`),
      this.storage.deleteItem(\`\${this.prefix}.refresh\`),
      this.storage.deleteItem(\`\${this.prefix}.meta\`),
    ]);
  }
}
`,
  });

  // 4. src/foundation/auth/AuthStateMachine.ts
  files.push({
    path: 'src/foundation/auth/AuthStateMachine.ts',
    ownership: 'generated',
    content: `${GENERATED_HEADER}

export type AuthStatus =
  | 'unknown'
  | 'restoring'
  | 'anonymous'
  | 'authenticating'
  | 'authenticated'
  | 'refreshing'
  | 'verifying'
  | 'challenge_required'
  | 'signing_out'
  | 'recovery_required'
  | 'error';

export interface AccessContext {
  authenticated: boolean;
  userId?: string;
  roles: string[];
  permissions: string[];
  verified: boolean;
  tenantId?: string;
  accountStatus?: string;
}

export interface AuthStateSnapshot {
  status: AuthStatus;
  accessContext: AccessContext;
  expiresAt: number | null;
  errorCode: string | null;
}

export class GeneratedAuthStateMachine {
  private snapshot: AuthStateSnapshot = {
    status: '${authIR.stateMachine.initialStatus}',
    accessContext: {
      authenticated: false,
      roles: [],
      permissions: [],
      verified: false,
    },
    expiresAt: null,
    errorCode: null,
  };

  private readonly listeners = new Set<(state: AuthStateSnapshot) => void>();

  getState(): AuthStateSnapshot {
    return this.snapshot;
  }

  setState(next: Partial<AuthStateSnapshot>): AuthStateSnapshot {
    this.snapshot = { ...this.snapshot, ...next };
    for (const listener of this.listeners) {
      listener(this.snapshot);
    }
    return this.snapshot;
  }

  subscribe(listener: (state: AuthStateSnapshot) => void): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }
}
`,
  });

  // 5. src/foundation/auth/SessionManager.ts
  files.push({
    path: 'src/foundation/auth/SessionManager.ts',
    ownership: 'generated',
    content: `${GENERATED_HEADER}
import { TokenManager, type StoredSessionMetadata } from './TokenManager';

export class SessionManager {
  private inflightRefresh: Promise<StoredSessionMetadata | null> | null = null;

  constructor(private readonly tokenManager: TokenManager) {}

  async restore(refreshFn: (refreshToken: string) => Promise<StoredSessionMetadata | null>): Promise<StoredSessionMetadata | null> {
    const meta = await this.tokenManager.getMetadata();
    if (!meta) return null;
    const now = Date.now();
    if (now + ${authIR.sessionPolicy.refreshThresholdSeconds * 1000} < meta.expiresAt) {
      return meta;
    }
    if (!${String(authIR.sessionPolicy.refreshEnabled)}) {
      await this.tokenManager.clear();
      return null;
    }
    return this.refresh(refreshFn);
  }

  async refresh(refreshFn: (refreshToken: string) => Promise<StoredSessionMetadata | null>): Promise<StoredSessionMetadata | null> {
    if (this.inflightRefresh) {
      return this.inflightRefresh;
    }
    this.inflightRefresh = (async () => {
      const refreshToken = await this.tokenManager.getRefreshToken();
      if (!refreshToken) {
        await this.tokenManager.clear();
        return null;
      }
      return refreshFn(refreshToken);
    })().finally(() => {
      this.inflightRefresh = null;
    });
    return this.inflightRefresh;
  }
}
`,
  });

  // 6. src/foundation/auth/adapters/PrimaryAdapter.ts
  files.push({
    path: 'src/foundation/auth/adapters/PrimaryAdapter.ts',
    ownership: 'generated',
    content: `${GENERATED_HEADER}
import { AUTH_CONFIG } from '../../config/auth.generated';

export const PRIMARY_PROVIDER_TYPE = AUTH_CONFIG.primaryProvider.type;
export const PRIMARY_PROVIDER_CONFIG = AUTH_CONFIG.primaryProvider.config;
`,
  });

  // 7. src/foundation/auth/AuthController.ts
  files.push({
    path: 'src/foundation/auth/AuthController.ts',
    ownership: 'generated',
    content: `${GENERATED_HEADER}
import { AUTH_CONFIG } from '../config/auth.generated';
import { GeneratedAuthStateMachine, type AuthStateSnapshot } from './AuthStateMachine';
import { ExpoSecureStorage } from './SecureStorage';
import { TokenManager } from './TokenManager';
import { SessionManager } from './SessionManager';

export class GeneratedAuthController {
  readonly stateMachine = new GeneratedAuthStateMachine();
  readonly storage = new ExpoSecureStorage();
  readonly tokenManager = new TokenManager(this.storage);
  readonly sessionManager = new SessionManager(this.tokenManager);
  readonly config = AUTH_CONFIG;

  getState(): AuthStateSnapshot {
    return this.stateMachine.getState();
  }

  subscribe(listener: (state: AuthStateSnapshot) => void): () => void {
    return this.stateMachine.subscribe(listener);
  }
}
`,
  });

  // 8. src/foundation/auth/AuthProvider.tsx (Headless Context Provider — zero visual UI components)
  files.push({
    path: 'src/foundation/auth/AuthProvider.tsx',
    ownership: 'generated',
    content: `${GENERATED_HEADER}
import React, { createContext, useContext, useEffect, useState } from 'react';
import { GeneratedAuthController } from './AuthController';
import type { AuthStateSnapshot } from './AuthStateMachine';

const AuthContext = createContext<{
  controller: GeneratedAuthController;
  state: AuthStateSnapshot;
} | null>(null);

export function AuthFoundationProvider(props: {
  controller: GeneratedAuthController;
  children: React.ReactNode;
}) {
  const [state, setState] = useState<AuthStateSnapshot>(() => props.controller.getState());

  useEffect(() => {
    return props.controller.subscribe(setState);
  }, [props.controller]);

  return (
    <AuthContext.Provider value={{ controller: props.controller, state }}>
      {props.children}
    </AuthContext.Provider>
  );
}

export function useAuthFoundation() {
  const ctx = useContext(AuthContext);
  if (!ctx) {
    throw new Error('useAuthFoundation must be used within <AuthFoundationProvider>.');
  }
  return ctx;
}
`,
  });

  return files;
}
